    display: flex;
    flex-direction: column;
    background: #e8e8e8;
    border-right: 1px solid #000;
  }

  .tech-tab {
    height: 48px;
    padding: 0 20px;
    text-align: left;
    background: none;
    border: none;
    border-bottom: 1px solid #000;
    cursor: pointer;
    display: flex;
    align-items: center;
    transition: background 0.15s;
  }

  .tech-tab:last-child {
    border-bottom: none;
  }

  .tech-tab span {
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    font-family: 'Courier New', Courier, monospace;
  }

  .tech-tab--inactive {
    background: #e8e8e8;
    color: #555;
  }

  .tech-tab--inactive:hover {
    background: #d8d8d8;
  }

  .tech-tab--active {
    background: #fff;
    color: #000;
    /* extend 1 px to the right to cover the sidebar border */
    width: calc(100% + 1px);
    position: relative;
    z-index: 2;
    border-right: 1px solid #fff;
    margin-right: -1px;
  }

  /* ── Content ── */
  .tech-content {
    flex: 1;
    padding: 40px 48px;
    background: #fff;
    overflow-y: auto;
  }

  .tech-content h3 {
    font-size: 28px;
